-- Only Once (`only-once@1`): seven questions, never the same answer twice,
-- verified by the database.
--
-- One kind of thing a day — countries, US states or chemical elements — and seven
-- questions about it, broad first and narrow last. Each accepted answer is a move:
-- the id of the thing named. It must be a right answer to its question and must
-- not have been given before. Ten points a question, thirty more for all seven.
--
--   1. The rules version and the bank: every puzzle's seven answer sets as hex
--      bitmasks over the kind's ids (four ids a digit, lowest first), generated from
--      `src/lib/games/only-once-bank.ts` by `bun scripts/generate-daily-banks.ts
--      --write`.
--   2. `only_once_score(day, actions)`: the replay, null for a run that is not legal.
--   3. `complete_only_once_run`, the verifier, as Guesswork's.
--   4. The registry row. The day seed is `20270104120400_daily_four_start.sql`.
--
-- The 25-second clock is the player's own and is not replayed: the verifier proves
-- a run is legal, not that a person played it. Nothing a user can see changes until
-- `20270104120500_daily_four_playable.sql`. Mirrored by src/lib/games/only-once.ts.

create or replace function public.only_once_rules_version()
returns text language sql immutable set search_path = '' as $$ select 'only-once@1'::text $$;

create or replace function public.only_once_max_actions()
returns integer language sql immutable set search_path = '' as $$ select 7 $$;

comment on function public.only_once_rules_version() is 'The Only Once rules version: only-once@1.';
comment on function public.only_once_max_actions() is
  'The most moves one Only Once submission may carry: seven answers.';

