comment on function public.only_once_bank() is
  'only-once@1''s puzzles: day d is puzzle d mod n, each [kind, seven hex answer masks]. Generated from src/lib/games/only-once-bank.ts.';

-- Whether id `p_id` is in a hex mask: digit id / 4, bit id mod 4.
create or replace function public.only_once_has(p_mask text, p_id integer)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_id >= 0
     and p_id / 4 < char_length(p_mask)
     and ((position(substr(p_mask, p_id / 4 + 1, 1) in '0123456789abcdef') - 1)
          >> (p_id % 4)) & 1 = 1
$$;

create or replace function public.only_once_score(p_day bigint, p_actions integer[])
returns bigint
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_bank   jsonb := public.only_once_bank();
  v_n      integer := jsonb_array_length(public.only_once_bank());
  v_puzzle jsonb;
  v_used   integer[] := '{}';
  v_action integer;
  v_q      integer := 0;
begin
  v_puzzle := v_bank -> ((((p_day % v_n) + v_n) % v_n)::integer);
  foreach v_action in array coalesce(p_actions, '{}'::integer[]) loop
    if v_q >= 7 or v_action = any(v_used)
       or not public.only_once_has(v_puzzle ->> (v_q + 1), v_action) then
      return null;
    end if;
    v_used := v_used || v_action;
    v_q := v_q + 1;
  end loop;
  return v_q * 10 + case when v_q >= 7 then 30 else 0 end;
end;
$$;

comment on function public.only_once_score(bigint, integer[]) is
  'An Only Once day''s answers replayed: 10 each and 30 more for all seven; null when an answer is wrong for its question or given twice.';

revoke all on function public.only_once_has(text, integer) from public;
revoke all on function public.only_once_score(bigint, integer[]) from public;

create or replace function public.complete_only_once_run(
  p_session_id  uuid,
  p_actions     integer[],
  p_score       bigint,
  p_duration_ms integer
)
returns public.play_result
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_gate   record;
  v_result public.play_result;
  v_score  bigint;
begin
  select * into v_gate from public.speed_run_gate(
    p_session_id, p_actions, p_score, p_duration_ms,
    public.only_once_rules_version(), public.only_once_max_actions());
  if (v_gate.refusal).outcome is not null then
    return v_gate.refusal;
  end if;

  v_result.session_id := (v_gate.session).id;
  v_result.game_slug := (v_gate.game).slug;

  if (v_gate.session).user_id is not null and exists (
    select 1
      from public.game_sessions s
     where s.game_id = (v_gate.session).game_id
       and s.user_id = (v_gate.session).user_id
       and s.seed = (v_gate.session).seed
       and s.id <> (v_gate.session).id
       and s.completed_at is not null
  ) then
    v_result.outcome := 'already_played';
    return v_result;
  end if;

  v_score := public.only_once_score((v_gate.session).seed, p_actions);
  if v_score is null then
    v_result.outcome := 'invalid_actions';
    return v_result;
  end if;

  if p_score is distinct from v_score then
    v_result.outcome := 'score_mismatch';
    v_result.score := v_score;
    return v_result;
  end if;

  return public.speed_run_finish(
    v_gate.session, v_gate.game, v_gate.digest, v_score,
    0, v_gate.elapsed, coalesce(cardinality(p_actions), 0),
    coalesce(cardinality(p_actions), 0), p_duration_ms);
end;
$$;

comment on function public.complete_only_once_run(uuid, integer[], bigint, integer) is
  'Only Once: replays a day''s answers on the day''s puzzle and records the score.';

revoke all on function public.complete_only_once_run(uuid, integer[], bigint, integer) from public;
grant execute on function public.complete_only_once_run(uuid, integer[], bigint, integer) to anon, authenticated;

insert into public.game_runtimes (runtime, rules_version, max_actions, session_hours) values
  ('only-once', public.only_once_rules_version(), public.only_once_max_actions(), 2)
on conflict (runtime, rules_version) do update
  set max_actions   = excluded.max_actions,
      session_hours = excluded.session_hours;
